   room has three public names). Byte mode, error correction M, versions 1-10 (up to 213 bytes at M): an address is
   40-60 bytes. Pure and dependency-free; the module grid is the whole output. After Nayuki's QR Code generator
   (public-domain reference algorithm, written out here from the ISO 18004 tables for V1-V10).
   tests/browser/test_v53_entry.py decodes the rendered code with OpenCV's reader when it is installed. */

const ECC_PER_BLOCK_M = [0, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26];
const BLOCKS_M = [0, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5];
const FORMAT_M = 0;

const rawModules = (version: number): number => {
  let result = (16 * version + 128) * version + 64;
  if (version >= 2) {
    const aligns = Math.floor(version / 7) + 2;
    result -= (25 * aligns - 10) * aligns - 55;
    if (version >= 7) result -= 36;
  }
  return result;
};

const dataCodewords = (version: number): number =>
  Math.floor(rawModules(version) / 8) - ECC_PER_BLOCK_M[version] * BLOCKS_M[version];

const gfMultiply = (x: number, y: number): number => {
  let z = 0;
  for (let i = 7; i >= 0; i--) {
    z = (z << 1) ^ ((z >>> 7) * 0x11d);
    z ^= ((y >>> i) & 1) * x;
  }
  return z;
};

const reedSolomonDivisor = (degree: number): number[] => {
  const result = new Array<number>(degree).fill(0);
  result[degree - 1] = 1;
  let root = 1;
  for (let i = 0; i < degree; i++) {
    for (let j = 0; j < degree; j++) {
      result[j] = gfMultiply(result[j], root);
      if (j + 1 < degree) result[j] ^= result[j + 1];
    }
    root = gfMultiply(root, 0x02);
  }
  return result;
};

const reedSolomonRemainder = (data: number[], divisor: number[]): number[] => {
  const result = new Array<number>(divisor.length).fill(0);
  for (const byte of data) {
    const factor = byte ^ (result.shift() as number);
    result.push(0);
    divisor.forEach((coefficient, i) => {
      result[i] ^= gfMultiply(coefficient, factor);
    });
  }
  return result;
};

const bit = (value: number, index: number): boolean => ((value >>> index) & 1) !== 0;

const encodeBytes = (bytes: number[], version: number): number[] => {
