/* V-53: /start in the game look. Public page: no session, no cookie, nothing that mints authority. This file only
   opens the sheets (help, addresses, licence), pages the long guide so nothing scrolls, and draws the QR of the
   address the page was opened on. It has no player-facing string: every word is in start.html. */

import { qrModules, qrSvg } from "./qr";
import "./start.css";

const all = <T extends Element>(selector: string, root: ParentNode = document): T[] =>
  Array.from(root.querySelectorAll<T>(selector));
const one = <T extends Element>(selector: string, root: ParentNode = document): T => {
  const node = root.querySelector<T>(selector);
  if (!node) throw new Error(`start page lost ${selector}`);
  return node;
};

// Embers: decoration only, kept inside their layer so nothing spills past a box.
const embers = one<HTMLElement>(".embers");
for (let n = 0; n < 16; n++) {
  const ember = document.createElement("i");
  ember.style.cssText =
    `--x:${(4 + Math.random() * 90).toFixed(1)}%;--s:${(3 + Math.random() * 5).toFixed(1)}px;` +
    `--dx:${Math.round((Math.random() - 0.5) * 60)}px;--d:${(8 + Math.random() * 9).toFixed(1)}s;` +
    `--w:${(-Math.random() * 16).toFixed(1)}s`;
  embers.appendChild(ember);
}

for (const link of all<HTMLAnchorElement>("[data-host]")) {
  if (link.dataset.host === location.hostname) link.setAttribute("aria-current", "true");
}

// The QR names the address this page was opened on, so scanning it from the table lands a phone on the same host.
const paintQr = (): void => {
  const holder = one<HTMLElement>("[data-testid='start-qr']");
  const address = `${location.origin}/start`;
  holder.innerHTML = qrSvg(qrModules(address), "#0B0907", "#EFE3C8");
  holder.dataset.address = address;
};

// The guide in pages that fit the box: as many whole steps as it holds, then the arrows.
const pager = one<HTMLElement>(".pager");
const steps = all<HTMLLIElement>("ol.steps > li");
const label = one<HTMLElement>("[data-testid='start-page']");
const back = one<HTMLButtonElement>("[data-step='-1']");
const next = one<HTMLButtonElement>("[data-step='1']");
const pages: HTMLLIElement[][] = [[]];
let page = 0;
const show = (): void => {
  steps.forEach((step) => { step.hidden = !pages[page].includes(step); });
  label.textContent = `${page + 1} / ${pages.length}`;
  back.disabled = page === 0;
  next.disabled = page === pages.length - 1;
  one<HTMLElement>(".pages").hidden = pages.length < 2;
};
const paginate = (): void => {
  if (!pager.clientHeight) return;
  pages.length = 0;
  pages.push([]);
  steps.forEach((step) => { step.hidden = true; });
  for (const step of steps) {
    step.hidden = false;
    if (pager.scrollHeight > pager.clientHeight + 1 && pages[pages.length - 1].length) {
      pages[pages.length - 1].forEach((shown) => { shown.hidden = true; });
      pages.push([]);
    }
    pages[pages.length - 1].push(step);
  }
  page = Math.min(page, pages.length - 1);
  show();
};
for (const button of all<HTMLButtonElement>("[data-step]")) {
  button.addEventListener("click", () => {
    page = Math.max(0, Math.min(pages.length - 1, page + Number(button.dataset.step)));
    show();
  });
}

// Help sheet: four pictures first; the full guide one tap further.
const help = one<HTMLDialogElement>("#sheet-help");
const view = (name: "quick" | "full"): void => {
  one<HTMLElement>("[data-view='quick']", help).hidden = name !== "quick";
  one<HTMLElement>("[data-view='full']", help).hidden = name !== "full";
  help.dataset.view = name;
  if (name === "full") paginate();
};
for (const button of all<HTMLButtonElement>("[data-show]", help)) {
  button.addEventListener("click", () => view(button.dataset.show === "full" ? "full" : "quick"));
}

const opener = new WeakMap<HTMLDialogElement, HTMLElement>();
for (const button of all<HTMLButtonElement>("[data-sheet]")) {
  button.addEventListener("click", () => {
    const sheet = one<HTMLDialogElement>(`#sheet-${button.dataset.sheet}`);
    opener.set(sheet, button);
    if (sheet === help) view("quick");
    if (typeof sheet.showModal === "function") sheet.showModal();
    else sheet.setAttribute("open", "");
    if (button.dataset.sheet === "hosts") paintQr();
  });
}
for (const sheet of all<HTMLDialogElement>("dialog.sheet")) {
  sheet.addEventListener("click", (event) => { if (event.target === sheet) sheet.close(); });
  sheet.addEventListener("close", () => opener.get(sheet)?.focus());
}
for (const button of all<HTMLButtonElement>("[data-close]")) {
  button.addEventListener("click", () => button.closest("dialog")?.close());
}
addEventListener("resize", () => { if (help.open && help.dataset.view === "full") paginate(); });
